afterEach(function(done) {
    expect(fs.existsSync(this.blogDirectory + this.path)).toEqual(false);
    this.client
      .filesGetMetadata({
        path: this.folder + this.path,
        include_deleted: true
      })
      .then(function(res) {
        // Verify file no longer exists on Dropbox
        expect(res[".tag"]).toEqual("deleted");
        // Verify the file no longer exists in blog folder
        done();
      })
      .catch(function(err) {
        if (err && err.status === 409) return done();
        done(new Error(err));
      });
  })

afterEach(function(done) {
    var contents = this.contents;
    expect(
      fs.readFileSync(this.blogDirectory + this.path).toString("utf-8")
    ).toEqual(contents);
    this.client
      .filesDownload({ path: this.folder + this.path })
      .then(function(res) {
        // Check file exists in blog directory in Dropbox
        expect(res.fileBinary.toString("utf-8")).toEqual(contents);
        done();
      })
      .catch(function(err) {
        done(new Error(err));
      });
  })

